/*
    Código JavaScript
    flow.getVar('nome_var') - pega o valor da variável
    flow.setVar('nome_var', 'valor') - seta um novo valor para variável
    emulator.log('texto') - mostra o log no emulador de teste
*/

// Pega o telefone do contato
let telefoneCompleto = flow.getVar('CONTATO.TELEFONE');

// Garante que seja string e evita null/undefined
telefoneCompleto = telefoneCompleto ? String(telefoneCompleto) : '';

// Remove o código do país '55' apenas se existir
let telefoneSemPais = telefoneCompleto.startsWith('55') ? telefoneCompleto.slice(2) : telefoneCompleto;

// Seta a nova variável no Flow
flow.setVar('TELEFONE_SEM_55', telefoneSemPais);

// Monta o link atualizado substituindo a variável
let linkBase = "https://sistema.vivamaisplan.com.br/loja/?route=product/add_cart/add_products&produtos[0][id]=46&produtos[0][quantidade]=1&user_afiliate=mariana_mendonca&set_store_id=38&set_telephone=";

let linkAtualizado = linkBase + telefoneSemPais;

// Seta no Flow a variável LINK_ATUALIZADO
flow.setVar('LINK_ATUALIZADO', linkAtualizado);

// Logs para teste no emulador
emulator.log('Telefone tratado (sem 55 se presente): ' + telefoneSemPais);
emulator.log('Link atualizado: ' + linkAtualizado);
